const cfg=window.ORL_CONFIG||{},$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
let token=sessionStorage.getItem('orl_session_token')||'',user=null,pendingRequest=null,currentPage='dashboard';
const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
const themes=[{id:'TAUPE',name:'Warm Taupe',primary:'#815854',secondary:'#F9EBDE'},{id:'RUBY',name:'Ruby Gold',primary:'#A4193D',secondary:'#FFDFB9'},{id:'ROSE',name:'Rose Slate',primary:'#6A7BA2',secondary:'#FFDFDE'},{id:'PURPLE',name:'Purple Sage',primary:'#603F83',secondary:'#C7D3D4'},{id:'OCEAN',name:'Ocean Blue',primary:'#0063B2',secondary:'#9CC3D5'}];
const esc=v=>{const d=document.createElement('div');d.textContent=v??'';return d.innerHTML};
async function rpc(name,args={}){const r=await fetch(`${cfg.supabaseUrl}/rest/v1/rpc/${name}`,{method:'POST',headers:{'Content-Type':'application/json',apikey:cfg.supabaseAnonKey,Authorization:`Bearer ${cfg.supabaseAnonKey}`},body:JSON.stringify(args)});let data=null;try{data=await r.json()}catch{}if(!r.ok)throw new Error(data?.message||'Unable to connect to the ORL database.');return data}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').hidden=false}function closeModal(){$('#modal').hidden=true}
function head(title,sub=''){return `<h1 class="title">${title}</h1><p class="sub">${sub}</p>`}
function field(label,name,type='text',wide=''){return `<div class="field ${wide}"><label>${label}<input name="${name}" type="${type}" required></label></div>`}
function status(v){return `<span class="badge ${esc(v)}">${esc(v)}</span>`}
function admissionDate(ot,holidays=[]){let d=new Date(ot+'T12:00:00');d.setDate(d.getDate()-2);const blocked=new Set(holidays.map(x=>x.holiday_date));while([5,6].includes(d.getDay())||blocked.has(d.toISOString().slice(0,10)))d.setDate(d.getDate()-1);return d.toISOString().slice(0,10)}
function go(page){currentPage=page;$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#pageTitle').textContent=$(`#nav [data-page="${page}"]`)?.textContent.replace(/^[^A-Za-z]+/,'')||'';document.body.classList.remove('menu-open');({dashboard,schedule,submit,requests,account,management,postponed,deletions,holidays,users,audit,settings,database}[page]||dashboard)()}
async function dashboard(){const c=$('#content');c.innerHTML=head('Welcome, '+esc(user.display_name),'ORL operating theatre overview.')+'<div class="card empty">Loading dashboard…</div>';try{const d=await rpc('orl_get_dashboard',{p_session_token:token});c.innerHTML=head('Welcome, '+esc(user.display_name),'ORL operating theatre overview.')+`<div class="cards"><div class="card stat"><b>${d.draft}</b><span>Draft</span></div><div class="card stat"><b>${d.confirmed}</b><span>Confirmed / Reserved</span></div><div class="card stat"><b>${d.scheduled}</b><span>Scheduled</span></div><div class="card stat"><b>${d.upcoming_ot}</b><span>Upcoming OT Days</span></div></div><section class="block"><h2>Quick Actions</h2><div class="card actions"><button class="primary" onclick="go('submit')">Submit New Request</button><button class="secondary" onclick="go('schedule')">View OT Schedule</button></div></section>`}catch(e){c.innerHTML+=`<div class="card empty">${esc(e.message)}</div>`}}
async function schedule(year,month){
  const now=new Date(),y=year||now.getFullYear(),m=month||1,c=$('#content');
  c.innerHTML=head('OT Schedule')+`<div class="toolbar card"><label>Year<select id="sy" onchange="schedule(+this.value,1)">${[2026,2027,2028,2029,2030,2031].map(x=>`<option ${x===y?'selected':''}>${x}</option>`).join('')}</select></label><div class="schedule-info">OT Days: <b>Sunday & Wednesday</b> &nbsp;|&nbsp; Main Slots: <b>5</b> &nbsp;|&nbsp; Special Slots: <b>2</b></div></div><div id="monthTabs" class="month-tabs"></div><div id="specialDays"></div><div id="scheduleList" class="schedule old-style"><div class="card empty">Loading…</div></div>`;
  $$('#content .admin').forEach(x=>x.hidden=user.role==='STAFF');
  try{
    const [rows,hs,counts,specials]=await Promise.all([rpc('orl_get_schedule',{p_session_token:token,p_year:y,p_month:m}),rpc('orl_list_holidays',{p_session_token:token}),rpc('orl_get_year_month_counts',{p_session_token:token,p_year:y}),rpc('orl_get_special_ot_days',{p_session_token:token,p_year:y})]);
    window._schedule=rows;window._scheduleYM={year:y,month:m};window._holidays=hs;
    $('#monthTabs').innerHTML=counts.map(x=>`<button class="month-tab ${x.month===m?'active':''}" onclick="schedule(${y},${x.month})">${months[x.month-1]}<small>${x.available} available</small></button>`).join('');
    $('#specialDays').innerHTML=specials.length?`<section class="card special-directory"><h2>🏷️ Special OT Days This Year</h2>${specials.map(x=>`<div class="special-directory-row" onclick="showSpecialDate('${x.date}')"><div><b>${esc(x.title)}</b><small>${esc(x.day_name)}, ${x.date}</small></div><button class="secondary mini">Show Date →</button></div>`).join('')}</section>`:'';
    $('#scheduleList').innerHTML=rows.map(s=>scheduleCard(s,hs)).join('')||'<div class="card empty">No OT sessions for this month.</div>';
  }catch(e){$('#scheduleList').innerHTML=`<div class="card empty">${esc(e.message)}<br>Workflow package 009 must be installed first.</div>`}
}
function scheduleCard(s,hs){const available=s.slots.filter(x=>x.status==='AVAILABLE').length,reserved=s.slots.filter(x=>x.status==='RESERVED').length,confirmed=s.slots.filter(x=>x.status==='CONFIRMED').length,admin=user.role!=='STAFF',preview=s.slots.map(x=>`<span class="collapsed-slot ${x.request_status==='CANCELLED'?'cancelled':x.status.toLowerCase()}">${x.type==='SPECIAL'?'★':''}S${x.number}</span>`).join('');return `<article class="session-card ${s.status.toLowerCase()}" id="d-${s.ot_date}"><div class="session-head"><div><div class="session-date">${esc(s.day_name)}, ${s.ot_date} ${status(s.status)} ${s.special_title?`<span class="badge">🏷️ ${esc(s.special_title)}</span>`:''} ${s.holiday_name?`<em>${esc(s.holiday_name)}</em>`:''}</div><div class="admit">Admission: ${admissionDate(s.ot_date,hs)}</div><div class="session-summary"><span>${available} Available</span><span>${confirmed} Confirmed</span>${reserved?`<span>${reserved} Reserved</span>`:''}</div></div><div class="session-controls">${admin?`<button class="mini" onclick="setTitle('${s.session_id}')">🏷️ Title</button>${s.status==='ACTIVE'?`<button class="danger mini" onclick="setSession('${s.session_id}','CANCELLED')">Cancel OT</button>`:`<button class="mini" onclick="setSession('${s.session_id}','ACTIVE')">Activate (Override)</button>`}`:''}<button class="session-toggle" onclick="toggleOT('${s.ot_date}',this)">View OT ▾</button></div></div><div class="collapsed-slots">${preview}</div><div class="slot-grid">${s.slots.map(sl=>slotCard(sl,s,admin)).join('')}</div></article>`}
function slotCard(sl,s,admin){const filled=!!sl.patient_name,label=(sl.type==='SPECIAL'?'★ Special Slot ':'Main Slot ')+sl.number,pick=pendingRequest&&sl.status==='AVAILABLE'&&(user.role!=='STAFF'||sl.type!=='SPECIAL'),cancelled=sl.request_status==='CANCELLED';return `<div class="slot-detail ${cancelled?'cancelled':sl.status.toLowerCase()}"><div class="slot-title"><span>${label}</span>${status(cancelled?'CANCELLED':sl.status)}</div>${filled?`<b class="patient">${esc(sl.patient_name)}</b><div class="patient-meta">IC: ${esc(sl.patient_ic)} &nbsp; MRN: ${esc(sl.mrn)}<br>Procedure: ${esc(sl.surgery)}<br>Diagnosis: ${esc(sl.diagnosis)}<br>Doctor: ${esc(sl.doctor)} ${sl.specialist?` | Specialist: ${esc(sl.specialist)}`:''}<br>${status(sl.sub_specialty)}<br>Phone: ${esc(sl.phone)}${sl.remark?`<br>Remark: ${esc(sl.remark)}`:''}</div>${sl.postpone_count?`<span class="badge">🔁 Postponed ×${sl.postpone_count}</span>`:''}`:''}<div class="slot-actions">${pick?`<button class="primary mini" onclick="assignSlot('${sl.id}')">Assign OT Slot</button>`:''}${filled?`<button class="mini" onclick="postponeSlot('${sl.id}')">Postpone</button>${admin&&sl.type==='MAIN'?`<button class="mini" onclick="reassignSlot('${s.session_id}','${sl.id}')">← Reassign</button>`:''}<button class="mini" onclick="editSlot('${sl.id}')">Edit</button>${admin?`<button class="danger mini" onclick="clearSlot('${sl.id}')">Clear</button>`:''}`:''}${admin&&!filled&&!pick?`<span class="muted">Available</span>`:''}</div></div>`}
function toggleOT(date,b){const card=document.getElementById('d-'+date),open=card.classList.toggle('open');b.textContent=open?'Hide OT ▴':'View OT ▾'}
function reloadSchedule(){return schedule(window._scheduleYM?.year||new Date().getFullYear(),window._scheduleYM?.month||1)}
async function setSession(id,state){if(!confirm(`${state==='CANCELLED'?'Cancel':'Activate'} this OT date?`))return;try{await rpc('orl_set_session',{p_session_token:token,p_session_id:id,p_status:state,p_title:null});reloadSchedule()}catch(e){toast(e.message)}}
async function setTitle(id){const title=prompt('Special OT title:');if(title===null)return;try{await rpc('orl_set_session',{p_session_token:token,p_session_id:id,p_status:null,p_title:title});reloadSchedule()}catch(e){toast(e.message)}}
async function clearSlot(id){if(!confirm('Clear this patient from the OT slot?'))return;try{await rpc('orl_clear_slot',{p_session_token:token,p_slot_id:id});toast('OT slot cleared.');reloadSchedule()}catch(e){toast(e.message)}}
function postponeSlot(id){const all=(window._schedule||[]).flatMap(x=>x.slots),x=all.find(s=>s.id===id),session=(window._schedule||[]).find(s=>s.slots.some(a=>a.id===id)),y=window._scheduleYM.year;modal(`<h2>🔁 Postpone Patient</h2><div class="card">Original slot: <b>${session.ot_date} — ${x.type} Slot ${x.number}</b></div><form id="postponeForm"><h3>Patient Details (editable)</h3><div class="grid">${field('Patient IC','patient_ic')}${field('MRN','mrn')}${field('Patient Name','patient_name')}${field('Surgery / Procedure','surgery')}${field('Diagnosis','diagnosis')}${field('Doctor','doctor')}${field('Specialist','specialist')}${field('Sub-specialty','sub_specialty')}${field('Phone','phone')}<div class="field wide"><label>Remark<textarea name="remark"></textarea></label></div></div><h3>Move To New Date</h3><div class="toolbar"><label>New Year<select id="postYear">${[2026,2027,2028,2029,2030,2031].map(v=>`<option ${v===y?'selected':''}>${v}</option>`).join('')}</select></label><label>New Month<select id="postMonth">${months.map((v,i)=>`<option value="${i+1}">${v}</option>`).join('')}</select></label></div><div class="field"><label>Postpone Reason<input name="reason" placeholder="e.g. Patient unwell / OT full" required></label></div><div id="postSlots" class="card empty">Choose year and month.</div></form>`);['patient_ic','mrn','patient_name','surgery','diagnosis','doctor','specialist','sub_specialty','phone','remark'].forEach(k=>{$(`#postponeForm [name="${k}"]`).value=x[k]||''});$('#postMonth').value=window._scheduleYM.month;$('#postYear').onchange=loadPostponeSlots;$('#postMonth').onchange=loadPostponeSlots;window._postponeFrom=id;loadPostponeSlots()}
async function loadPostponeSlots(){const y=+$('#postYear').value,m=+$('#postMonth').value,box=$('#postSlots');box.innerHTML='Loading available slots…';try{const rows=await rpc('orl_get_schedule',{p_session_token:token,p_year:y,p_month:m});box.innerHTML=rows.map(s=>`<div class="post-date"><b>${esc(s.day_name)}, ${s.ot_date}</b><div class="slots">${s.slots.filter(x=>x.status==='AVAILABLE'&&(user.role!=='STAFF'||x.type!=='SPECIAL')).map(x=>`<button type="button" class="slot ${x.type==='SPECIAL'?'special':''}" onclick="completePostpone('${x.id}')">${x.type==='SPECIAL'?'★':''}S${x.number}</button>`).join('')||'<span class="muted">No available slots</span>'}</div></div>`).join('')||'No OT dates.'}catch(e){box.textContent=e.message}}
async function completePostpone(toId){const form=$('#postponeForm'),d=Object.fromEntries(new FormData(form)),reason=d.reason;if(!reason?.trim()){toast('Please enter a postpone reason.');return}delete d.reason;try{const result=await rpc('orl_move_postponed',{p_session_token:token,p_from_slot_id:window._postponeFrom,p_to_slot_id:toId,p_data:d,p_reason:reason});closeModal();toast(result==='RESERVED'?'New slot reserved for Admin confirmation.':'Patient postponed to the new slot.');reloadSchedule()}catch(e){toast(e.message)}}
function reassignSlot(sessionId,fromId){const session=(window._schedule||[]).find(x=>x.session_id===sessionId),targets=session.slots.filter(x=>x.type==='MAIN'&&x.id!==fromId);modal(`<h2>↔ Reassign Main OT Slot</h2><p>Select another Main slot on ${session.ot_date}. If occupied, both patients will swap positions.</p><div class="slots">${targets.map(x=>`<button class="slot ${x.status.toLowerCase()}" onclick="swapSlot('${fromId}','${x.id}')">S${x.number}${x.patient_name?` — ${esc(x.patient_name)}`:' — Available'}</button>`).join('')}</div>`)}
async function swapSlot(fromId,toId){try{await rpc('orl_swap_slots',{p_session_token:token,p_from:fromId,p_to:toId});closeModal();toast('OT slots reassigned.');reloadSchedule()}catch(e){toast(e.message)}}
function editSlot(id){const all=(window._schedule||[]).flatMap(x=>x.slots),x=all.find(s=>s.id===id),session=(window._schedule||[]).find(s=>s.slots.some(a=>a.id===id));modal(`<h2>Edit Slot ${session.ot_date} ${x.type} ${x.number}</h2><form id="editSlotForm"><div class="grid">${field('Patient IC','patient_ic')}${field('MRN','mrn')}${field('Patient Name','patient_name','text','wide')}${field('Surgery / Procedure','surgery','text','wide')}${field('Diagnosis','diagnosis','text','wide')}${field('Doctor','doctor')}${field('Specialist','specialist')}${field('Phone','phone')}${field('Sub-specialty','sub_specialty')}<div class="field"><label>Status<select name="action"><option value="CONFIRM">Confirm</option><option value="POSTPONE">Postpone</option><option value="CANCEL">Cancel</option></select><small>Confirm = patient stays in slot<br>Postpone = select a new slot<br>Cancel = record retained with red background</small></label></div><div class="field wide"><label>Remark<textarea name="remark"></textarea></label></div></div><div class="actions"><button class="primary">Save</button><button type="button" class="secondary" onclick="closeModal()">Cancel</button></div></form>`);['patient_ic','mrn','patient_name','surgery','diagnosis','doctor','specialist','sub_specialty','phone','remark'].forEach(k=>{$(`#editSlotForm [name="${k}"]`).value=x[k]||''});$('#editSlotForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),action=d.action;delete d.action;if(action==='POSTPONE'){closeModal();postponeSlot(id);return}try{await rpc('orl_edit_scheduled_request',{p_session_token:token,p_slot_id:id,p_data:d,p_action:action});closeModal();toast(action==='CANCEL'?'Patient cancelled; record retained.':'Patient details updated.');reloadSchedule()}catch(z){toast(z.message)}}}
function submit(){const c=$('#content');c.innerHTML=head('Submit Request','Enter patient details, then select an available OT slot.')+`<form id="requestForm" class="card"><div class="grid">${field('Patient IC','patient_ic')}${field('MRN','mrn')}${field('Patient Name','patient_name')}${field('Surgery','surgery')}${field('Diagnosis','diagnosis')}${field('Doctor','doctor')}${field('Specialist','specialist')}<div class="field"><label>Sub-specialty<select name="sub_specialty"><option>Gen ORL</option><option>Rhinology</option><option>Otology</option><option>Head & Neck</option><option>Paeds</option></select></label></div>${field('Phone','phone')}<div class="field wide"><label>Remark<textarea name="remark" rows="3"></textarea></label></div></div><div class="actions"><button class="primary">Confirm and Choose Slot</button><span id="formMsg"></span></div></form>`;$('#requestForm').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;$('#formMsg').textContent='Saving…';try{const data=Object.fromEntries(new FormData(e.target)),id=await rpc('orl_create_request',{p_session_token:token,p_data:data});await rpc('orl_confirm_request',{p_session_token:token,p_request_id:id});pendingRequest=id;toast('Request saved. Choose an available slot.');schedule()}catch(x){$('#formMsg').textContent=x.message;btn.disabled=false}}}
async function assignSlot(id){try{const result=await rpc('orl_assign_slot',{p_session_token:token,p_request_id:pendingRequest,p_slot_id:id});pendingRequest=null;toast(result==='CONFIRMED'?'Patient assigned and confirmed.':'Slot reserved for Admin approval.');requests()}catch(e){toast(e.message)}}
async function requests(){return requestList(false)}async function management(){return requestList(true)}
async function requestList(admin){const c=$('#content');c.innerHTML=head(admin?'Request Management':'My Requests',admin?'Review, approve, reject, sort and manage requests.':'Track your submitted OT requests.')+`<div class="toolbar"><label>Status<select id="rf"><option value="">All</option>${['DRAFT','CONFIRMED','APPROVED','REJECTED','SCHEDULED','COMPLETED','CANCELLED'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>Sort<select id="rs"><option value="date">Date entered</option><option value="postpone">Postponed count</option></select></label><input id="rq" class="grow" placeholder="Search patient, MRN or request number"><button class="primary" onclick="drawRequests(${admin})">Apply</button></div><div id="requestRows" class="card empty">Loading…</div>`;await drawRequests(admin)}
async function drawRequests(admin){try{
  let rows=await rpc('orl_get_requests',{p_session_token:token}),q=($('#rq')?.value||'').toLowerCase(),f=$('#rf')?.value||'',sortBy=$('#rs')?.value||'date';
  rows=rows.filter(r=>(!f||r.status===f)&&(!q||JSON.stringify(r).toLowerCase().includes(q)));rows.sort(sortBy==='postpone'?(a,b)=>b.postpone_count-a.postpone_count:(a,b)=>new Date(b.created_at)-new Date(a.created_at));
  $('#requestRows').outerHTML=`<div id="requestRows" class="table-wrap"><table><thead><tr><th>Request</th><th>Patient / MRN</th><th>Surgery</th><th>OT Slot</th><th>Postponed</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="request-link" onclick="jumpToRequest('${r.ot_date||''}')">${esc(r.request_number)}</button><br><small>${new Date(r.created_at).toLocaleString()}</small></td><td>${esc(r.patient_name)}<br><small>${esc(r.mrn)}</small></td><td>${esc(r.surgery)}<br><small>${esc(r.doctor)}</small></td><td>${r.ot_date?`<button class="request-link" onclick="jumpToRequest('${r.ot_date}')">${r.ot_date}<br>${r.slot_type} S${r.slot_number}</button>`:'—'}</td><td>${r.postpone_count||0}</td><td>${status(r.status)}</td><td><div class="actions">${admin&&r.status==='CONFIRMED'?`<button class="mini" onclick="review('${r.id}','APPROVE')">Confirm</button><button class="mini" onclick="review('${r.id}','REJECT')">Reject</button>`:''}${r.assigned_slot_id?`<button class="mini" onclick="openEditFromRequest('${r.id}','${r.ot_date}')">Edit Request</button>`:''}${user.role==='WEBMASTER'?`<button class="danger mini" onclick="deleteRequest('${r.id}')">Delete</button>`:(r.status!=='CANCELLED'&&r.status!=='COMPLETED'&&r.deletion_status!=='PENDING'?`<button class="danger mini" onclick="requestDeletion('${r.id}')">Request Delete</button>`:'')}</div></td></tr>`).join('')}</tbody></table></div>`;
}catch(e){$('#requestRows').innerHTML=esc(e.message)+'<br>Workflow package 009 must be installed first.'}}
function jumpToRequest(date){if(!date){toast('This request has no OT slot yet.');return}const d=new Date(date+'T12:00:00');schedule(d.getFullYear(),d.getMonth()+1).then(()=>setTimeout(()=>{const card=document.getElementById('d-'+date);if(card){card.scrollIntoView({behavior:'smooth',block:'center'});if(!card.classList.contains('open'))card.querySelector('.session-toggle')?.click()}},100))}
async function openEditFromRequest(requestId,date){if(!date)return;const d=new Date(date+'T12:00:00');try{const rows=await rpc('orl_get_schedule',{p_session_token:token,p_year:d.getFullYear(),p_month:d.getMonth()+1}),slot=rows.flatMap(x=>x.slots).find(x=>x.request_id===requestId);window._schedule=rows;window._scheduleYM={year:d.getFullYear(),month:d.getMonth()+1};if(slot)editSlot(slot.id)}catch(e){toast(e.message)}}
async function review(id,action){const note=prompt(`${action} note (optional):`)??'';try{await rpc('orl_review_request',{p_session_token:token,p_request_id:id,p_action:action,p_note:note});toast(`Request ${action.toLowerCase()}d.`);management()}catch(e){toast(e.message)}}
async function deleteRequest(id){if(!confirm('Permanently delete this request? This cannot be undone.'))return;try{await rpc('orl_delete_request',{p_session_token:token,p_request_id:id});toast('Request deleted.');go(currentPage)}catch(e){toast(e.message)}}
async function editPostpone(id,n){const v=prompt('Postpone count:',n);if(v===null)return;try{await rpc('orl_set_postpone_count',{p_session_token:token,p_request_id:id,p_count:+v});toast('Postpone count updated.');go(currentPage)}catch(e){toast(e.message)}}
async function postponed(){const c=$('#content');c.innerHTML=head('Postponed Management','Patients with one or more postponements, including their complete history.')+`<div class="toolbar"><label>Sort By<select id="ps"><option value="earliest">Earliest Postponed</option><option value="count">Postpone Count (Most)</option><option value="name">Patient Name (A-Z)</option><option value="diagnosis">Case Type (Diagnosis)</option><option value="surgery">Procedure</option><option value="sub_specialty">Sub-specialty</option></select></label><input id="pq" class="grow" placeholder="Search name / IC / MRN"><button class="primary" onclick="drawPostponed()">Apply</button></div><div id="postponedRows" class="card empty">Loading…</div>`;try{window._postponed=await rpc('orl_get_postponed',{p_session_token:token});drawPostponed()}catch(e){$('#postponedRows').textContent=e.message}}
function drawPostponed(){let rows=(window._postponed||[]).slice(),q=($('#pq')?.value||'').toLowerCase(),by=$('#ps')?.value||'earliest';if(q)rows=rows.filter(x=>JSON.stringify(x).toLowerCase().includes(q));if(by==='count')rows.sort((a,b)=>b.postpone_count-a.postpone_count);else if(by==='name')rows.sort((a,b)=>a.patient_name.localeCompare(b.patient_name));else if(by!=='earliest')rows.sort((a,b)=>(a[by]||'').localeCompare(b[by]||''));else rows.sort((a,b)=>(a.first_postponed||'').localeCompare(b.first_postponed||''));$('#postponedRows').outerHTML=`<div id="postponedRows" class="table-wrap"><table><thead><tr><th>#</th><th>Patient</th><th>Procedure</th><th>Diagnosis</th><th>Sub-specialty</th><th>Doctor</th><th>Times</th><th>First / Last</th><th>Status</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td><b>${esc(r.patient_name)}</b><br><small>${esc(r.patient_ic)} | ${esc(r.mrn)}</small></td><td>${esc(r.surgery)}</td><td>${esc(r.diagnosis)}</td><td>${status(r.sub_specialty)}</td><td>${esc(r.doctor)}</td><td>${status('×'+r.postpone_count)}</td><td>${r.first_postponed?new Date(r.first_postponed).toLocaleString():'—'}<br>${r.last_postponed?new Date(r.last_postponed).toLocaleString():'—'}</td><td>${status(r.status)}</td><td><button class="mini" onclick="postponeHistory('${r.id}')">History</button>${user.role==='WEBMASTER'?` <button class="mini" onclick="editPostpone('${r.id}',${r.postpone_count})">Edit Count</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function postponeHistory(id){const r=(window._postponed||[]).find(x=>x.id===id),history=r?.history||[];modal(`<h2>Postpone History — ${esc(r.request_number)}</h2><p>Patient: <b>${esc(r.patient_name)}</b> — ${status('Postponed ×'+r.postpone_count)}</p>${history.length?`<div class="table-wrap"><table><thead><tr><th>#</th><th>Date/Time</th><th>By</th><th>From</th><th>To</th><th>Reason</th></tr></thead><tbody>${history.map((x,i)=>`<tr><td>${i+1}</td><td>${x.date||x.at?new Date(x.date||x.at).toLocaleString():'—'}</td><td>${esc(x.by)}</td><td>${esc(x.from||`${x.ot_date||''} ${x.slot?'Slot '+x.slot:''}`)}</td><td>${esc(x.to||'—')}</td><td>${esc(x.reason)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No detailed history recorded.</div>'}`)}
async function deletions(){const c=$('#content');c.innerHTML=head('Deletion Management','Review deletion requests. Approval cancels the case and releases its OT slot.')+'<div id="deletionRows" class="card empty">Loading…</div>';try{const rows=await rpc('orl_get_deletions',{p_session_token:token});$('#deletionRows').outerHTML=`<div id="deletionRows" class="table-wrap"><table><thead><tr><th>#</th><th>Request</th><th>Patient</th><th>Procedure</th><th>Status</th><th>Requested By</th><th>Reason</th><th>Requested On</th><th>Actions</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.request_number)}</td><td><b>${esc(r.patient_name)}</b><br><small>${esc(r.patient_ic)} | ${esc(r.mrn)}</small></td><td>${esc(r.surgery)}</td><td>${status(r.status)}</td><td>${esc(r.requested_by)}</td><td>${esc(r.reason)}</td><td>${new Date(r.requested_at).toLocaleString()}</td><td><button class="danger mini" onclick="resolveDeletion('${r.id}','APPROVE')">✓ Approve Delete</button> <button class="mini" onclick="resolveDeletion('${r.id}','REJECT')">✕ Reject</button></td></tr>`).join('')}</tbody></table></div>`}catch(e){$('#deletionRows').textContent=e.message}}
async function requestDeletion(id){const reason=prompt('Reason for deletion (sent to Admin for approval):');if(reason===null||!reason.trim())return;try{await rpc('orl_request_deletion',{p_session_token:token,p_request_id:id,p_reason:reason.trim()});toast('Deletion request sent to Admin.');requests()}catch(e){toast(e.message)}}
async function resolveDeletion(id,action){if(!confirm(action==='APPROVE'?'Approve deletion and cancel this case?':'Reject this deletion request?'))return;try{await rpc('orl_resolve_deletion',{p_session_token:token,p_request_id:id,p_action:action});toast(action==='APPROVE'?'Deletion approved.':'Deletion rejected.');deletions()}catch(e){toast(e.message)}}
async function holidays(){const c=$('#content'),year=new Date().getFullYear();c.innerHTML=head('Holiday Management','Generate National and Kedah public holidays by year, or manage custom blocked days.')+`<section class="card"><h2>Generate Malaysia Public Holidays</h2><div class="toolbar"><label>Year<input id="holidayYear" type="number" min="2026" max="2100" value="${year}"></label><button id="generateHolidayBtn" class="primary" onclick="generateHolidays()">Generate Public Holidays</button><small>Source: Calendar Malaysia. Existing dates will not be overwritten.</small></div></section><form id="holidayForm" class="card toolbar"><input type="hidden" name="id"><label>Date<input type="date" name="date" required></label><label class="grow">Title<input name="title" placeholder="Public holiday / course / clinic block" required></label><label class="grow">Description<input name="description"></label><button id="holidaySaveBtn" class="primary">Add Block</button><button id="holidayCancelBtn" type="button" class="secondary" hidden onclick="resetHolidayForm()">Cancel Edit</button></form><div id="holidayRows" class="card empty">Loading…</div>`;$('#holidayForm').onsubmit=saveHoliday;await loadHolidays()}
async function loadHolidays(){try{const rows=await rpc('orl_list_holidays',{p_session_token:token});window._holidayRows=rows;$('#holidayRows').outerHTML=`<div id="holidayRows" class="table-wrap"><table><thead><tr><th>Date</th><th>Title</th><th>Description</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${x.holiday_date}</td><td>${esc(x.title)}</td><td>${esc(x.description)}</td><td><button class="mini" onclick="editHoliday('${x.id}')">Edit</button> <button class="danger mini" onclick="deleteHoliday('${x.id}')">Delete</button></td></tr>`).join('')}</tbody></table></div>`}catch(e){$('#holidayRows').textContent=e.message}}
function editHoliday(id){const x=(window._holidayRows||[]).find(r=>r.id===id),f=$('#holidayForm');if(!x||!f)return;f.id.value=x.id;f.date.value=x.holiday_date;f.title.value=x.title;f.description.value=x.description||'';$('#holidaySaveBtn').textContent='Save Changes';$('#holidayCancelBtn').hidden=false;f.scrollIntoView({behavior:'smooth',block:'center'})}
function resetHolidayForm(){const f=$('#holidayForm');f.reset();f.id.value='';$('#holidaySaveBtn').textContent='Add Block';$('#holidayCancelBtn').hidden=true}
async function saveHoliday(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await rpc('orl_save_holiday',{p_session_token:token,p_id:d.id||null,p_date:d.date,p_title:d.title,p_description:d.description||''});toast(d.id?'Block updated.':'Block added.');holidays()}catch(x){toast(x.message)}}
async function generateHolidays(){const year=+$('#holidayYear').value,b=$('#generateHolidayBtn');if(year<2026||year>2100){toast('Choose a year between 2026 and 2100.');return}if(!confirm(`Generate National and Kedah public holidays for ${year}?`))return;b.disabled=true;b.textContent='Generating…';try{const r=await rpc('orl_generate_public_holidays',{p_session_token:token,p_year:year});toast(`${r.inserted} holiday(s) added; ${r.skipped} existing date(s) kept.`);await loadHolidays()}catch(e){toast(e.message)}finally{b.disabled=false;b.textContent='Generate Public Holidays'}}
async function deleteHoliday(id){if(confirm('Delete this block?')){try{await rpc('orl_delete_holiday',{p_session_token:token,p_id:id});holidays()}catch(e){toast(e.message)}}}
async function users(){const c=$('#content');c.innerHTML=head('User Management','Manage Webmaster, Admin and Staff accounts.')+`<button class="primary" onclick="userForm()">Add User</button><div id="userRows" class="card empty" style="margin-top:14px">Loading…</div>`;try{const rows=await rpc('orl_list_users',{p_session_token:token});rows.sort((a,b)=>(a.display_name||'').localeCompare(b.display_name||'',undefined,{sensitivity:'base'}));window._users=rows;$('#userRows').outerHTML=`<div id="userRows" class="user-role-groups">${['WEBMASTER','ADMIN','STAFF'].map(role=>userRoleSection(role,rows.filter(x=>x.role===role))).join('')}</div>`}catch(e){$('#userRows').textContent=e.message}}
function userRoleSection(role,rows){return `<section class="user-role-section"><div class="user-role-heading"><h2>${role[0]+role.slice(1).toLowerCase()}</h2><span>${rows.length} account${rows.length===1?'':'s'}</span></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Active</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.display_name)}</b></td><td>${esc(x.username)}</td><td>${x.is_active?'Yes':'No'}</td><td><button class="mini" onclick="userForm('${x.id}')">Edit</button> ${user.role==='WEBMASTER'&&x.id!==user.user_id?`<button class="danger mini" onclick="deleteUser('${x.id}')">Delete</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty">No accounts in this level.</div>'}</section>`}
function userForm(id=''){const x=(window._users||[]).find(u=>u.id===id)||{},password=id?'<div class="field"><label>New Password (leave blank to keep)<input name="password" type="password"></label></div>':field('Password','password','password');modal(`<h2>${id?'Edit':'Add'} User</h2><form id="uf"><div class="grid">${field('Name','display_name')}${field('Username','username')}<div class="field"><label>Role<select name="role"><option>STAFF</option><option>ADMIN</option>${user.role==='WEBMASTER'?'<option>WEBMASTER</option>':''}</select></label></div>${password}<div class="field"><label><input style="width:auto;display:inline" type="checkbox" name="active" checked> Active</label></div></div><div class="actions"><button class="primary">Save User</button></div></form>`);$('#uf [name=display_name]').value=x.display_name||'';$('#uf [name=username]').value=x.username||'';$('#uf [name=role]').value=x.role||'STAFF';$('#uf [name=active]').checked=x.is_active!==false;$('#uf').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await rpc('orl_save_user',{p_session_token:token,p_id:id||null,p_username:d.username,p_display_name:d.display_name,p_role:d.role,p_password:d.password||'',p_active:!!d.active});closeModal();toast('User saved.');users()}catch(z){toast(z.message)}}}
async function deleteUser(id){if(!confirm('Permanently delete this user account?'))return;try{await rpc('orl_delete_user',{p_session_token:token,p_id:id});toast('User deleted.');users()}catch(e){toast(e.message)}}
async function account(){const c=$('#content');c.innerHTML=head('Account Settings','Change your password and personal colour theme.')+'<div class="card empty">Loading account settings…</div>';try{const rows=await rpc('orl_get_account_settings',{p_session_token:token}),a=rows[0];if(!a)throw new Error('Account settings are unavailable.');user.theme=a.theme||'OCEAN';applyTheme(user.theme);c.innerHTML=head('Account Settings','Settings are saved separately for '+esc(a.display_name)+'.')+`<div class="account-grid"><section class="card account-panel"><h2>Change Password</h2><p>Use at least 8 characters. Changing your password signs out any other active sessions.</p><form id="passwordForm"><div class="field"><label>Current Password<input name="current_password" type="password" autocomplete="current-password" required></label></div><div class="field"><label>New Password<input name="new_password" type="password" minlength="8" autocomplete="new-password" required></label></div><div class="field"><label>Confirm New Password<input name="confirm_password" type="password" minlength="8" autocomplete="new-password" required></label></div><div class="actions"><button class="primary">Change Password</button></div></form></section><section class="card account-panel theme-panel"><h2>Colour Theme</h2><p>Select a colour composition. Your choice follows your account on every device.</p><div class="theme-options">${themes.map(t=>themeOption(t,user.theme)).join('')}</div></section></div>`;$('#passwordForm').onsubmit=changeOwnPassword}catch(e){c.innerHTML=head('Account Settings')+`<div class="card empty">${esc(e.message)}<br>Account Settings package 017 must be installed first.</div>`}}
function themeOption(t,selected){return `<button class="theme-option ${t.id===selected?'selected':''}" style="--theme-primary:${t.primary};--theme-secondary:${t.secondary}" onclick="saveTheme('${t.id}')"><span class="theme-colours"><i></i><i></i></span><b>${t.name}</b><small>${t.primary} · ${t.secondary}</small><strong>${t.id===selected?'Selected':'Choose Theme'}</strong></button>`}
function applyTheme(theme){const chosen=themes.some(t=>t.id===theme)?theme:'OCEAN';document.body.dataset.theme=chosen;if(user?.username)localStorage.setItem('orl_theme_'+user.username.toLowerCase(),chosen)}
async function loadAccountTheme(){const cached=localStorage.getItem('orl_theme_'+user.username.toLowerCase());applyTheme(cached||'OCEAN');try{const rows=await rpc('orl_get_account_settings',{p_session_token:token});if(rows[0]){user.theme=rows[0].theme||'OCEAN';applyTheme(user.theme)}}catch{}}
async function saveTheme(theme){try{const saved=await rpc('orl_update_theme',{p_session_token:token,p_theme:theme});user.theme=saved;applyTheme(saved);toast('Colour theme saved.');account()}catch(e){toast(e.message)}}
async function changeOwnPassword(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),b=e.submitter;if(d.new_password!==d.confirm_password){toast('New passwords do not match.');return}b.disabled=true;b.textContent='Changing…';try{await rpc('orl_change_own_password',{p_session_token:token,p_current_password:d.current_password,p_new_password:d.new_password});e.target.reset();toast('Password changed successfully.')}catch(x){toast(x.message)}finally{b.disabled=false;b.textContent='Change Password'}}
async function audit(){const c=$('#content');c.innerHTML=head('Audit Log','Latest 500 recorded system activities.')+`<div class="toolbar"><input id="aq" class="grow" placeholder="Search audit records"><button class="primary" onclick="loadAudit()">Search</button></div><div id="auditRows" class="card empty">Loading…</div>`;await loadAudit()}
async function loadAudit(){try{const rows=await rpc('orl_get_audit',{p_session_token:token,p_search:$('#aq')?.value||''});$('#auditRows').outerHTML=`<div id="auditRows" class="table-wrap"><table><thead><tr><th>Date / Time</th><th>User</th><th>Role</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${new Date(x.occurred_at).toLocaleString()}</td><td>${esc(x.user_name)}</td><td>${esc(x.user_role)}</td><td>${esc(x.action)}</td><td>${esc(x.record_id)}</td><td>${esc(x.details)}</td></tr>`).join('')}</tbody></table></div>`}catch(e){$('#auditRows').textContent=e.message}}
async function settings(){const c=$('#content');c.innerHTML=head('Settings','System year range, OT days and slot capacity.')+'<div class="card empty">Loading…</div>';try{const s=await rpc('orl_get_settings',{p_session_token:token});c.innerHTML=head('Settings','System year range, OT days and slot capacity.')+`<form id="settingsForm" class="card"><div class="grid">${field('System Name','SYSTEM_NAME')}${field('Start Year','START_YEAR','number')}${field('End Year','END_YEAR','number')}${field('OT Days (0=Sunday, 3=Wednesday)','OT_DAYS')}${field('Main Slots','MAIN_SLOTS','number')}${field('Special Slots','SPECIAL_SLOTS','number')}</div><div class="actions"><button class="primary">Save Settings</button></div></form>`;Object.entries(s).forEach(([k,v])=>{const el=$(`#settingsForm [name="${k}"]`);if(el)el.value=v});$('#settingsForm').onsubmit=async e=>{e.preventDefault();try{await rpc('orl_save_settings',{p_session_token:token,p_data:Object.fromEntries(new FormData(e.target))});toast('Settings saved.')}catch(x){toast(x.message)}}}catch(e){c.innerHTML+=`<div class="card empty">${esc(e.message)}</div>`}}
async function dashboard(){const c=$('#content');c.innerHTML=head('Welcome, '+esc(user.display_name),'ORL operating theatre overview.')+'<div class="card empty">Loading dashboard…</div>';try{const d=await rpc('orl_get_dashboard',{p_session_token:token});c.innerHTML=head('Welcome, '+esc(user.display_name),'ORL operating theatre overview.')+`<div class="cards"><div class="card stat"><b>${d.draft}</b><span>Draft</span></div><div class="card stat"><b>${d.confirmed}</b><span>Confirmed / Reserved</span></div><div class="card stat"><b>${d.scheduled}</b><span>Scheduled</span></div><div class="card stat"><b>${d.upcoming_ot}</b><span>Upcoming OT Days</span></div></div><section class="block"><h2>Find Patient Record</h2><form id="patientSearch" class="card toolbar"><label class="grow">MRN Number<input id="patientMrn" placeholder="Enter exact MRN number" required></label><button class="primary">Find Patient</button></form><div id="patientResults"></div></section><section class="block"><h2>Quick Actions</h2><div class="card actions"><button class="primary" onclick="go('submit')">Submit New Request</button><button class="secondary" onclick="go('schedule')">View OT Schedule</button></div></section>`;$('#patientSearch').onsubmit=findPatient}catch(e){c.innerHTML+=`<div class="card empty">${esc(e.message)}</div>`}}
async function findPatient(e){e.preventDefault();const box=$('#patientResults');box.innerHTML='<div class="card empty">Searching…</div>';try{const rows=await rpc('orl_find_patient',{p_session_token:token,p_mrn:$('#patientMrn').value.trim()});box.innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Request</th><th>Patient</th><th>Procedure / Diagnosis</th><th>OT Slot</th><th>Postponed</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.request_number)}<br><small>${new Date(r.created_at).toLocaleString()}</small></td><td><b>${esc(r.patient_name)}</b><br>MRN: ${esc(r.mrn)}<br><small>IC: ${esc(r.patient_ic)}</small></td><td>${esc(r.surgery)}<br><small>${esc(r.diagnosis)}</small></td><td>${r.ot_date?`<button class="request-link" onclick="jumpToRequest('${r.ot_date}')">${r.ot_date}<br>${r.slot_type} S${r.slot_number}</button>`:'—'}</td><td>${r.postpone_count||0}</td><td>${status(r.status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="card empty">No patient record found for this MRN.</div>'}catch(x){box.innerHTML=`<div class="card empty">${esc(x.message)}</div>`}}
function drawPostponed(){let rows=(window._postponed||[]).slice(),q=($('#pq')?.value||'').toLowerCase(),by=$('#ps')?.value||'earliest';if(q)rows=rows.filter(x=>JSON.stringify(x).toLowerCase().includes(q));if(by==='count')rows.sort((a,b)=>b.postpone_count-a.postpone_count);else if(by==='name')rows.sort((a,b)=>a.patient_name.localeCompare(b.patient_name));else if(by!=='earliest')rows.sort((a,b)=>(a[by]||'').localeCompare(b[by]||''));else rows.sort((a,b)=>(a.first_postponed||'').localeCompare(b.first_postponed||''));$('#postponedRows').outerHTML=`<div id="postponedRows" class="table-wrap"><table><thead><tr><th>#</th><th>Patient</th><th>Procedure</th><th>Diagnosis</th><th>Sub-specialty</th><th>Doctor</th><th>Times Postponed</th><th>First Postponed</th><th>Last Postponed</th><th>Status</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td><b>${esc(r.patient_name)}</b><br><small>${esc(r.patient_ic)} | ${esc(r.mrn)}</small></td><td>${esc(r.surgery)}</td><td>${esc(r.diagnosis)}</td><td>${r.sub_specialty?status(r.sub_specialty):'—'}</td><td>${esc(r.doctor)}</td><td>${status('🔁 ×'+r.postpone_count)}</td><td>${r.first_postponed?new Date(r.first_postponed).toLocaleString():'—'}</td><td>${r.last_postponed?new Date(r.last_postponed).toLocaleString():'—'}</td><td>${status(r.status)}</td><td><button class="mini" onclick="postponeHistory('${r.id}')">History</button></td></tr>`).join('')}</tbody></table></div>`}
function editSlot(id){const all=(window._schedule||[]).flatMap(x=>x.slots),x=all.find(s=>s.id===id),session=(window._schedule||[]).find(s=>s.slots.some(a=>a.id===id)),countField=user.role==='WEBMASTER'?field('Postpone Count','postpone_count','number'):'';modal(`<h2>Edit Slot ${session.ot_date} ${x.type} ${x.number}</h2><form id="editSlotForm"><div class="grid">${field('Patient IC','patient_ic')}${field('MRN','mrn')}${field('Patient Name','patient_name','text','wide')}${field('Surgery / Procedure','surgery','text','wide')}${field('Diagnosis','diagnosis','text','wide')}${field('Doctor','doctor')}${field('Specialist','specialist')}${field('Phone','phone')}${field('Sub-specialty','sub_specialty')}${countField}<div class="field"><label>Status<select name="action"><option value="CONFIRM">Confirm</option><option value="POSTPONE">Postpone</option><option value="CANCEL">Cancel</option></select><small>Confirm = patient stays in slot<br>Postpone = select a new slot<br>Cancel = record retained with red background</small></label></div><div class="field wide"><label>Remark<textarea name="remark"></textarea></label></div></div><div class="actions"><button class="primary">Save</button><button type="button" class="secondary" onclick="closeModal()">Cancel</button></div></form>`);['patient_ic','mrn','patient_name','surgery','diagnosis','doctor','specialist','sub_specialty','phone','remark','postpone_count'].forEach(k=>{const el=$(`#editSlotForm [name="${k}"]`);if(el)el.value=x[k]??''});$('#editSlotForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target)),action=d.action,count=d.postpone_count;delete d.action;delete d.postpone_count;if(action==='POSTPONE'){Object.assign(x,d);closeModal();postponeSlot(id);return}try{await rpc('orl_edit_scheduled_request',{p_session_token:token,p_slot_id:id,p_data:d,p_action:action});if(user.role==='WEBMASTER'&&count!=='')await rpc('orl_set_postpone_count',{p_session_token:token,p_request_id:x.request_id,p_count:+count});closeModal();toast(action==='CANCEL'?'Patient cancelled; record retained.':'Patient details updated.');reloadSchedule()}catch(z){toast(z.message)}}}
async function restore(){if(!token)return;try{const rows=await rpc('orl_current_user',{p_session_token:token});if(rows[0]){user=rows[0];show()}}catch{sessionStorage.removeItem('orl_session_token')}}
async function refreshNotifications(){if(user.role==='STAFF')return;try{const n=await rpc('orl_get_notifications',{p_session_token:token});const rb=$('[data-page="management"]'),db=$('[data-page="deletions"]');rb.innerHTML=`📁 Request Management ${n.requests?`<i class="nav-badge">${n.requests}</i>`:''}`;db.innerHTML=`🗑️ Deletion Management ${n.deletions?`<i class="nav-badge">${n.deletions}</i>`:''}`}catch{}}
function slotCard(sl,s,admin){const filled=!!sl.patient_name,label=(sl.type==='SPECIAL'?'★ Special Slot ':'Main Slot ')+sl.number,pick=pendingRequest&&sl.status==='AVAILABLE'&&(user.role!=='STAFF'||sl.type!=='SPECIAL'),cancelled=sl.request_status==='CANCELLED';return `<div class="slot-detail ${cancelled?'cancelled':sl.status.toLowerCase()}"><div class="slot-title"><span>${label}</span>${status(cancelled?'CANCELLED':sl.status)}</div>${filled?`<b class="patient">${esc(sl.patient_name)}</b><div class="patient-meta">IC: ${esc(sl.patient_ic)} &nbsp; MRN: ${esc(sl.mrn)}<br>Procedure: ${esc(sl.surgery)}<br>Diagnosis: ${esc(sl.diagnosis)}<br>Doctor: ${esc(sl.doctor)} ${sl.specialist?` | Specialist: ${esc(sl.specialist)}`:''}<br>${status(sl.sub_specialty)}<br>Phone: ${esc(sl.phone)}${sl.remark?`<br>Remark: ${esc(sl.remark)}`:''}</div>${sl.postpone_count?`<span class="badge">🔁 Postponed ×${sl.postpone_count}</span>`:''}`:''}<div class="slot-actions">${pick?`<button class="primary mini" onclick="assignSlot('${sl.id}')">Assign OT Slot</button>`:''}${filled?`<button class="mini" onclick="postponeSlot('${sl.id}')">Postpone</button>${admin&&sl.type==='MAIN'?`<button class="mini" onclick="reassignSlot('${s.session_id}','${sl.id}')">← Reassign</button>`:''}<button class="mini" onclick="editSlot('${sl.id}')">Edit</button>${admin?`<button class="danger mini" onclick="clearSlot('${sl.id}')">Clear</button>`:''}`:admin&&sl.status==='AVAILABLE'?`<button class="close-slot mini" onclick="setSlotClosed('${sl.id}',true)">🔒 Close Slot</button>`:admin&&sl.status==='CLOSED'?`<button class="mini" onclick="setSlotClosed('${sl.id}',false)">🔓 Reopen Slot</button>`:''}</div></div>`}
async function setSlotClosed(id,closed){if(!confirm(`${closed?'Close':'Reopen'} this OT slot?`))return;try{await rpc('orl_set_slot_closed',{p_session_token:token,p_slot_id:id,p_closed:closed});toast(closed?'OT slot closed.':'OT slot reopened.');reloadSchedule()}catch(e){toast(e.message)}}
async function dashboard(){const c=$('#content'),admin=user.role!=='STAFF',wm=user.role==='WEBMASTER';c.innerHTML=head('Welcome, '+esc(user.display_name),'Your ORL operating theatre overview and priority actions.')+'<div class="card empty">Loading dashboard…</div>';try{const d=await rpc('orl_get_dashboard',{p_session_token:token}),next=d.next_ot||null,cap=d.month_capacity||{},actions=d.pending_actions||{},admissions=d.upcoming_admissions||[],alerts=d.postponed_alerts||[],special=d.special_days||[],activity=d.recent_activity||[];c.innerHTML=head('Welcome, '+esc(user.display_name),'Your ORL operating theatre overview and priority actions.')+`<div class="cards dashboard-stats">${dashStat(admin?d.upcoming_ot:d.scheduled,admin?'Upcoming OT Days':'My Scheduled Patients','📅')}${dashStat(d.reserved??d.confirmed,admin?'Reserved Slots':'My Reserved Requests','⏳')}${dashStat(d.pending_cancellations||0,admin?'Pending Cancellations':'My Cancellation Requests','🗑️')}${dashStat(d.postponed||0,admin?'Postponed Patients':'My Postponed Patients','🔁')}${dashStat(d.available_month||0,'Available Slots This Month','✓')}</div><section class="block"><h2>Find Patient Record</h2><form id="patientSearch" class="card toolbar dashboard-search"><label class="grow">MRN Number<input id="patientMrn" placeholder="Enter exact MRN number" required></label><button class="primary">Find Patient</button></form><div id="patientResults"></div></section>${admin?`<section class="block"><h2>Pending Actions</h2><div class="dashboard-actions">${dashAction(actions.requests||0,'Requests awaiting confirmation','management')}${dashAction(actions.cancellations||0,'Cancellation requests to review','deletions')}${dashAction(actions.reserved||0,'Reserved slots requiring attention','management')}${wm?dashAction(actions.database_warnings||0,'Database warnings','database'):''}</div></section>`:''}<div class="dashboard-grid"><section class="card dashboard-panel"><h2>Next OT Day</h2>${next?`<button class="dashboard-next" onclick="jumpToRequest('${next.date}')"><b>${esc(next.day_name)}, ${next.date}</b>${next.title?`<span>🏷️ ${esc(next.title)}</span>`:''}<span>Admission: ${next.admission_date||'—'}</span><small>${next.available} Available · ${next.reserved} Reserved · ${next.confirmed} Confirmed · ${next.closed} Closed</small></button>`:'<div class="empty">No upcoming active OT date.</div>'}</section><section class="card dashboard-panel"><h2>This Month's OT Capacity</h2><div class="capacity-list">${capacityRow('Available',cap.available||0,'available')}${capacityRow('Reserved',cap.reserved||0,'reserved')}${capacityRow('Confirmed',cap.confirmed||0,'confirmed')}${capacityRow('Closed',cap.closed||0,'closed')}</div></section></div><div class="dashboard-grid"><section class="card dashboard-panel"><h2>Upcoming Admissions</h2>${admissions.length?`<div class="dashboard-list">${admissions.map(x=>`<button onclick="jumpToRequest('${x.ot_date}')"><span><b>${esc(x.patient_name)}</b><small>MRN: ${esc(x.mrn)} · ${esc(x.surgery)}</small></span><span class="list-date">Admit ${x.admission_date}<small>OT ${x.ot_date}</small></span></button>`).join('')}</div>`:'<div class="empty">No upcoming admissions.</div>'}</section><section class="card dashboard-panel"><h2>Repeatedly Postponed</h2>${alerts.length?`<div class="dashboard-list">${alerts.map(x=>`<button ${x.ot_date?`onclick="jumpToRequest('${x.ot_date}')"`:''}><span><b>${esc(x.patient_name)}</b><small>MRN: ${esc(x.mrn)} · ${esc(x.surgery)}</small></span><span class="postpone-pill">×${x.postpone_count}</span></button>`).join('')}</div>`:'<div class="empty">No patient postponed two or more times.</div>'}</section></div>${special.length?`<section class="card dashboard-panel block"><h2>🏷️ Special OT This Year</h2><div class="dashboard-special">${special.map(x=>`<button onclick="showSpecialDate('${x.ot_date}')"><b>${esc(x.special_title)}</b><span>${esc(x.day_name)}, ${x.ot_date} →</span></button>`).join('')}</div></section>`:''}${wm?`<section class="card dashboard-panel block"><h2>Recent System Activity</h2>${activity.length?`<div class="activity-list">${activity.map(x=>`<div><span>${new Date(x.occurred_at).toLocaleString()}</span><b>${esc(x.user_name||'System')}</b><strong>${esc(x.action.replaceAll('_',' '))}</strong><small>${esc(x.details)}</small></div>`).join('')}</div>`:'<div class="empty">No recent activity.</div>'}</section>`:''}<section class="block"><h2>Quick Actions</h2><div class="card actions"><button class="primary" onclick="go('submit')">Submit New Request</button><button class="secondary" onclick="go('schedule')">View OT Schedule</button>${admin?'<button class="secondary" onclick="go(\'management\')">Review Requests</button>':''}</div></section>`;$('#patientSearch').onsubmit=findPatient}catch(e){c.innerHTML=head('Welcome, '+esc(user.display_name),'ORL operating theatre overview.')+`<div class="card empty">${esc(e.message)}<br>Dashboard package 015 must be installed first.</div>`}}
function dashStat(value,label,icon){return `<div class="card stat dashboard-stat"><i>${icon}</i><b>${value??0}</b><span>${label}</span></div>`}
function dashAction(value,label,page){return `<button class="card dashboard-action" onclick="go('${page}')"><b>${value}</b><span>${label}</span><strong>Open →</strong></button>`}
function capacityRow(label,value,kind){return `<div class="capacity-row ${kind}"><span>${label}</span><b>${value}</b></div>`}
function modal(html){const cancelHelp=user?.role==='STAFF'?'Cancel = sent to Admin/Webmaster for review; slot remains reserved':'Cancel = OT slot released; patient record retained';$('#modalBody').innerHTML=html.replace('Cancel = record retained with red background',cancelHelp);$('#modal').hidden=false;const form=$('#editSlotForm'),select=form?.querySelector('[name="action"]');if(form&&select&&user?.role==='STAFF'){const remark=form.querySelector('[name="remark"]')?.closest('.field');remark?.insertAdjacentHTML('beforebegin','<div class="field wide" id="cancelReasonField" hidden><label>Cancellation Reason<input name="cancel_reason" placeholder="Reason for Admin/Webmaster review"></label></div>');select.onchange=()=>{const f=$('#cancelReasonField'),input=f?.querySelector('input');if(f){f.hidden=select.value!=='CANCEL';input.required=select.value==='CANCEL'}}}}
function toast(s){if(user?.role==='STAFF'&&s==='Patient cancelled; record retained.')s='Cancellation request sent for Admin/Webmaster review. The OT slot remains reserved.';$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function setTitle(id){const s=(window._schedule||[]).find(x=>x.session_id===id);modal(`<h2>OT day title for ${s.ot_date}</h2><p>(e.g.: Laser Day, Rhino Day, Paeds Day)<br>Leave empty to remove the title.</p><form id="titleForm"><div class="field"><input name="title" value="${esc(s.special_title||'')}" autofocus></div><div class="actions title-actions"><button class="primary">OK</button><button type="button" class="secondary" onclick="closeModal()">Cancel</button></div></form>`);$('#titleForm').onsubmit=async e=>{e.preventDefault();try{await rpc('orl_set_session',{p_session_token:token,p_session_id:id,p_status:null,p_title:new FormData(e.target).get('title').trim()});closeModal();toast('OT day title updated.');reloadSchedule()}catch(x){toast(x.message)}}}
async function showSpecialDate(date){const d=new Date(date+'T12:00:00');await schedule(d.getFullYear(),d.getMonth()+1);setTimeout(()=>{const card=document.getElementById('d-'+date);if(card){card.scrollIntoView({behavior:'smooth',block:'center'});card.classList.add('date-highlight')}},100)}
async function database(){if(user.role!=='WEBMASTER'){go('dashboard');return}const c=$('#content');c.innerHTML=head('Database Management','Webmaster-only tools for database inspection, backup, repair and controlled data removal.')+`<div id="dbStats" class="cards"><div class="card empty">Loading database overview…</div></div><div class="db-tabs"><button onclick="dbFind()">Find Patient</button><button onclick="dbCancelled()">Cancelled Records</button><button onclick="dbDuplicates()">Duplicate Detector</button><button onclick="dbHealth()">Orphan Checker & Repair</button><button onclick="dbAudit()">Audit Cleanup</button><button onclick="dbImport()">Import Backup</button><button onclick="dbExport()">Export Backup</button></div><div id="dbBody"></div>`;try{const d=await rpc('orl_db_overview',{p_session_token:token});$('#dbStats').innerHTML=`<div class="card stat"><b>${d.patients}</b><span>Patients</span></div><div class="card stat"><b>${d.requests}</b><span>Requests</span></div><div class="card stat"><b>${d.active_slots}</b><span>Occupied Slots</span></div><div class="card stat"><b>${d.cancelled}</b><span>Cancelled</span></div><div class="card stat"><b>${d.postponed}</b><span>Postponed</span></div><div class="card stat"><b>${d.users}</b><span>Users</span></div><div class="card stat"><b>${d.audit}</b><span>Audit Records</span></div><div class="card stat"><b>${formatBytes(d.database_bytes)}</b><span>Database Size</span></div>`;dbFind()}catch(e){$('#dbBody').innerHTML=`<div class="card empty">${esc(e.message)}<br>Database Management package 012 must be installed first.</div>`}}
const formatBytes=n=>{n=Number(n)||0;if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';return(n/1048576).toFixed(1)+' MB'};
function dbFind(){$('#dbBody').innerHTML=`<section class="db-panel"><h2>Find Patient Data</h2><form id="dbFindForm" class="toolbar"><label class="grow">MRN, Patient IC, Name or Request ID<input id="dbMrn" required></label><button class="primary">Find</button></form><div id="dbResults"></div></section>`;$('#dbFindForm').onsubmit=async e=>{e.preventDefault();const query=$('#dbMrn').value.trim(),box=$('#dbResults');box.innerHTML='<div class="empty">Searching…</div>';try{const rows=await rpc('orl_db_find_patient',{p_session_token:token,p_query:query}),sameMrn=rows.length>0&&rows[0].mrn&&rows.every(r=>r.mrn===rows[0].mrn);box.innerHTML=rows.length?dbPatientTable(rows,sameMrn):'<div class="empty">No matching patient records.</div>'}catch(x){box.innerHTML=`<div class="empty">${esc(x.message)}</div>`}}}
function dbPatientTable(rows,allowAll=false){return `<div class="table-wrap"><table><thead><tr><th>Request</th><th>Patient / MRN</th><th>Procedure</th><th>Status</th><th>Created</th><th>Permanent Removal</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.request_number)}</td><td><b>${esc(r.patient_name)}</b><br>${esc(r.mrn)}<br><small>${esc(r.patient_ic)}</small></td><td>${esc(r.surgery)}<br><small>${esc(r.diagnosis)}</small></td><td>${status(r.status)}</td><td>${new Date(r.created_at||r.cancelled_at).toLocaleString()}</td><td><button class="danger mini" onclick="dbRemove('REQUEST','${r.id}')">Remove This Record</button></td></tr>`).join('')}</tbody></table>${allowAll&&rows.length?`<div class="db-danger-zone"><button class="danger" onclick="dbRemove('MRN','${esc(rows[0].mrn)}')">Remove All Records for MRN ${esc(rows[0].mrn)}</button></div>`:''}</div>`}
async function dbCancelled(){$('#dbBody').innerHTML='<section class="db-panel"><h2>Cancelled Records</h2><div id="dbResults" class="empty">Loading…</div></section>';try{const rows=await rpc('orl_db_cancelled',{p_session_token:token});$('#dbResults').outerHTML=`<div id="dbResults">${rows.length?dbPatientTable(rows):'<div class="empty">No cancelled records.</div>'}</div>`}catch(e){$('#dbResults').textContent=e.message}}
async function dbDuplicates(){$('#dbBody').innerHTML='<section class="db-panel"><h2>Duplicate Patient Detector</h2><p>Potential duplicates are grouped by matching MRN or Patient IC. Review each record before removal.</p><div id="dbResults" class="empty">Scanning…</div></section>';try{const rows=await rpc('orl_db_duplicates',{p_session_token:token});$('#dbResults').outerHTML=`<div id="dbResults">${rows.length?rows.map(g=>`<div class="duplicate-group"><h3>${esc(g.match_type)}: ${esc(g.match_value)} <span class="badge">${g.record_count} records</span></h3>${dbPatientTable(g.records)}</div>`).join(''):'<div class="empty">No duplicate MRN or Patient IC detected.</div>'}</div>`}catch(e){$('#dbResults').textContent=e.message}}
async function dbHealth(){$('#dbBody').innerHTML='<section class="db-panel"><h2>Orphan Checker & Database Repair</h2><div id="dbResults" class="empty">Checking…</div></section>';try{const h=await rpc('orl_db_health',{p_session_token:token});const items=[['Scheduled without slot',h.scheduled_without_slot],['Request/slot mismatch',h.slot_request_mismatch],['Available slot containing patient',h.available_with_patient],['Empty slot marked occupied',h.occupied_marked_available],['Invalid reserved request',h.reserved_nonconfirmed_request]];$('#dbResults').outerHTML=`<div id="dbResults"><div class="health ${h.status.toLowerCase()}"><b>${h.status}</b></div><div class="cards health-cards">${items.map(x=>`<div class="card stat"><b>${x[1]}</b><span>${x[0]}</span></div>`).join('')}</div><div class="db-danger-zone"><p>Repair corrects mismatched statuses and request/slot links, then compacts every Main OT list.</p><button class="danger" onclick="dbRepair()">Run Database Repair</button></div></div>`}catch(e){$('#dbResults').textContent=e.message}}
function dbAudit(){$('#dbBody').innerHTML=`<section class="db-panel"><h2>Audit Log Cleanup</h2><p>Records before the selected date will be permanently removed. A new cleanup audit record will always be retained.</p><div class="toolbar"><label>Remove audit before<input id="auditBefore" type="date" required></label><button class="danger" onclick="dbCleanAudit()">Clean Audit Log</button></div></section>`}
async function dbRemove(mode,value){if(!confirm(mode==='MRN'?`Permanently remove ALL patient records for MRN ${value}?`:'Permanently remove this patient request record?'))return;secureDatabaseAction('Permanent Patient Removal','This cannot be undone. The affected OT slot will be released and Main slots compacted.',async password=>{const n=await rpc('orl_db_remove_patient',{p_session_token:token,p_password:password,p_mode:mode,p_value:value});toast(`${n} patient record(s) removed.`);database()})}
async function dbRepair(){if(!confirm('Run database repair and compact all Main OT slots?'))return;secureDatabaseAction('Database Repair','Review the health results before continuing.',async password=>{const r=await rpc('orl_db_repair',{p_session_token:token,p_password:password});toast(`Repair completed: ${r.fixed} item(s) corrected.`);dbHealth()})}
async function dbCleanAudit(){const date=$('#auditBefore').value;if(!date){toast('Select a cutoff date.');return}if(!confirm(`Permanently remove audit records before ${date}?`))return;secureDatabaseAction('Audit Log Cleanup','Deleted audit entries cannot be restored unless you exported a backup.',async password=>{const n=await rpc('orl_db_clean_audit',{p_session_token:token,p_password:password,p_before:date});toast(`${n} audit record(s) removed.`);database()})}
function dbExport(){modal(`<h2>🔐 Export Encrypted Backup</h2><div class="security-warning">The compressed .orlbackup file contains patient records. Keep its passphrase private.</div><form id="backupExportForm"><div class="field"><label>Webmaster Password<input name="password" type="password" autocomplete="current-password" required></label></div><div class="field"><label>Backup Passphrase<input name="passphrase" type="password" minlength="8" autocomplete="new-password" required></label></div><div class="field"><label>Confirm Backup Passphrase<input name="confirm_passphrase" type="password" minlength="8" autocomplete="new-password" required></label></div><label class="confirm-check"><input type="checkbox" required> I understand that this passphrase is required to restore the backup.</label><div class="actions"><button class="primary">Create Backup</button><button type="button" class="secondary" onclick="closeModal()">Cancel</button></div></form>`);$('#backupExportForm').onsubmit=exportEncryptedBackup}
async function exportEncryptedBackup(e){e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),b=e.submitter;if(d.passphrase!==d.confirm_passphrase){toast('Backup passphrases do not match.');return}b.disabled=true;b.textContent='Creating…';try{const data=await rpc('orl_db_export',{p_session_token:token,p_password:d.password}),plain=new TextEncoder().encode(JSON.stringify(data)),compressed=await streamBytes(plain,'gzip'),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await backupKey(d.passphrase,salt),cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,compressed)),magic=new TextEncoder().encode('ORLOMS1G'),blob=new Blob([magic,salt,iv,cipher],{type:'application/octet-stream'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`orl-backup-${new Date().toISOString().slice(0,10)}.orlbackup`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);closeModal();toast(`Encrypted backup downloaded (${formatBytes(blob.size)}).`)}catch(x){toast(x.message);b.disabled=false;b.textContent='Create Backup'}}
function dbImport(){$('#dbBody').innerHTML=`<section class="db-panel"><h2>Import Encrypted Backup</h2><div class="security-warning">Restore replaces current patient, schedule, holiday, settings and audit data. Existing login accounts are preserved.</div><form id="backupReadForm"><div class="field"><label>ORL Backup File<input name="file" type="file" accept=".orlbackup" required></label></div><div class="field"><label>Backup Passphrase<input name="passphrase" type="password" autocomplete="current-password" required></label></div><div class="actions"><button class="primary">Read and Verify Backup</button></div></form><div id="backupPreview"></div></section>`;$('#backupReadForm').onsubmit=previewBackup}
async function previewBackup(e){e.preventDefault();const d=new FormData(e.target),file=d.get('file'),box=$('#backupPreview'),b=e.submitter;b.disabled=true;b.textContent='Verifying…';try{window._restoreBackup=await decodeBackup(file,d.get('passphrase'));const x=window._restoreBackup;if(x.format!=='ORLOMS_BACKUP'||x.version!==1)throw new Error('Unsupported ORL backup format.');box.innerHTML=`<div class="backup-preview"><h3>Verified Backup</h3><p>Exported: <b>${new Date(x.exported_at).toLocaleString()}</b><br>By: <b>${esc(x.exported_by)}</b></p><div class="cards">${dashStat(x.requests?.length||0,'Requests','📁')}${dashStat(x.ot_slots?.length||0,'OT Slots','📅')}${dashStat(x.holidays?.length||0,'Holidays / Blocks','🌄')}${dashStat(x.audit_log?.length||0,'Audit Records','🧾')}</div><form id="backupRestoreForm"><div class="field"><label>Confirm Webmaster Password<input name="password" type="password" autocomplete="current-password" required></label></div><label class="confirm-check"><input type="checkbox" required> I understand that current operational data will be replaced by this backup.</label><div class="actions"><button class="danger">Restore This Backup</button></div></form></div>`;$('#backupRestoreForm').onsubmit=restoreBackup}catch(x){box.innerHTML=`<div class="card empty">${esc(x.message||'Unable to read backup.')}</div>`}finally{b.disabled=false;b.textContent='Read and Verify Backup'}}
async function restoreBackup(e){e.preventDefault();const b=e.submitter;if(!confirm('Replace current operational data with this verified backup?'))return;b.disabled=true;b.textContent='Restoring…';try{const r=await rpc('orl_db_import',{p_session_token:token,p_password:new FormData(e.target).get('password'),p_backup:window._restoreBackup});window._restoreBackup=null;toast(`Restore completed: ${r.requests} requests and ${r.slots} slots.`);database()}catch(x){toast(x.message);b.disabled=false;b.textContent='Restore This Backup'}}
async function backupKey(passphrase,salt){const base=await crypto.subtle.importKey('raw',new TextEncoder().encode(passphrase),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function streamBytes(bytes,mode){const stream=new Blob([bytes]).stream().pipeThrough(mode==='gzip'?new CompressionStream('gzip'):new DecompressionStream('gzip'));return new Uint8Array(await new Response(stream).arrayBuffer())}
async function decodeBackup(file,passphrase){const raw=new Uint8Array(await file.arrayBuffer());if(raw.length<36||new TextDecoder().decode(raw.slice(0,8))!=='ORLOMS1G')throw new Error('This is not a valid ORL encrypted backup.');try{const salt=raw.slice(8,24),iv=raw.slice(24,36),key=await backupKey(passphrase,salt),compressed=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,raw.slice(36)),plain=await streamBytes(new Uint8Array(compressed),'gunzip');return JSON.parse(new TextDecoder().decode(plain))}catch{throw new Error('Incorrect backup passphrase or damaged backup file.')}}
function secureDatabaseAction(title,warning,action,closeFirst=true){modal(`<h2>🔐 ${title}</h2><div class="security-warning">${esc(warning)}</div><form id="securityForm"><div class="field"><label>Confirm Webmaster Password<input name="password" type="password" autocomplete="current-password" required></label></div><label class="confirm-check"><input type="checkbox" required> I understand and confirm this action.</label><div class="actions"><button class="danger">Confirm</button><button type="button" class="secondary" onclick="closeModal()">Cancel</button></div></form>`);$('#securityForm').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;b.textContent='Processing…';try{if(closeFirst)closeModal();await action(new FormData(e.target).get('password'))}catch(x){toast(x.message);b.disabled=false;b.textContent='Confirm'}}}
function labelResponsiveTables(root=document){root.querySelectorAll('table').forEach(table=>{const labels=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());table.querySelectorAll('tbody tr').forEach(row=>[...row.children].forEach((cell,i)=>{if(cell.tagName==='TD')cell.dataset.label=labels[i]||''}))})}
const tableObserver=new MutationObserver(()=>labelResponsiveTables($('#content')));tableObserver.observe($('#content'),{childList:true,subtree:true});window.addEventListener('resize',()=>labelResponsiveTables($('#content')));document.addEventListener('click',e=>{if(innerWidth<=800&&document.body.classList.contains('menu-open')&&!e.target.closest('aside')&&!e.target.closest('#menu'))document.body.classList.remove('menu-open')});
function show(){$('#login').hidden=true;$('#app').hidden=false;$('#who').textContent=user.display_name;$('#role').textContent=user.role;$$('.admin').forEach(x=>x.hidden=user.role==='STAFF');if(user.role==='WEBMASTER'&&!$('[data-page="database"]'))$('#nav').insertAdjacentHTML('beforeend','<span class="webmaster-only">WEBMASTER</span><button data-page="database">🗄️ Database Management</button>');loadAccountTheme();refreshNotifications();go('dashboard')}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const b=$('#signIn');b.disabled=true;b.textContent='Signing in…';$('#loginMessage').textContent='';try{const rows=await rpc('orl_login',{p_username:$('#username').value.trim(),p_password:$('#password').value});if(!rows[0])throw new Error('Invalid username or password.');token=rows[0].session_token;sessionStorage.setItem('orl_session_token',token);user=rows[0];show()}catch(x){$('#loginMessage').textContent=x.message}finally{b.disabled=false;b.textContent='Sign In'}};
$('#logout').onclick=async()=>{try{await rpc('orl_logout',{p_session_token:token})}catch{}sessionStorage.clear();location.reload()};$('#nav').onclick=e=>{const b=e.target.closest('[data-page]');if(b)go(b.dataset.page)};$('#menu').onclick=()=>document.body.classList.toggle('menu-open');$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};restore();
